mapper.select:
select address_id, member_id, label, full_address, phone, is_default, create_time, update_time
from mall_address
where address_id = #{addressId}

mapper.update:
update mall_address
label = #{label}, full_address = #{fullAddress}, phone = #{phone}, is_default = #{isDefault}, update_time = #{updateTime}
where address_id = #{addressId}
